#!/usr/bin/env python3
"""Probe one explicitly selected TCP endpoint; no subnet or port scanning."""
import argparse
from datetime import datetime, timezone
import ipaddress
import json
from pathlib import Path
import platform
import socket
import subprocess
import sys
import time


def check_port(value):
    value = int(value)
    if not 1 <= value <= 65535:
        raise argparse.ArgumentTypeError("port must be between 1 and 65535")
    return value


def check_timeout(value):
    value = float(value)
    if not 0 < value <= 10:
        raise argparse.ArgumentTypeError("timeout must be greater than 0 and at most 10 seconds")
    return value


def probe(host, port, timeout):
    # Accept a numeric address so DNS cannot introduce an unbounded resolver wait.
    address = ipaddress.ip_address(host)
    family = socket.AF_INET6 if address.version == 6 else socket.AF_INET
    started = time.monotonic()
    try:
        with socket.socket(family, socket.SOCK_STREAM) as client:
            client.settimeout(timeout)
            client.connect((str(address), port))
        return {"connected": True, "elapsed_ms": round((time.monotonic()-started)*1000, 3)}
    except OSError as error:
        return {"connected": False, "elapsed_ms": round((time.monotonic()-started)*1000, 3),
                "error_type": type(error).__name__, "error": str(error)}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--host", default="127.0.0.1", help="One numeric IPv4 or IPv6 address you own or may test.")
    parser.add_argument("--port", type=check_port, default=8765)
    parser.add_argument("--timeout", type=check_timeout, default=1.0)
    parser.add_argument("--ping", action="store_true", help="Also send three ICMP requests on Linux.")
    parser.add_argument("--output", type=Path, default=Path("reports/network.json"))
    args = parser.parse_args()
    try:
        ipaddress.ip_address(args.host)
    except ValueError:
        parser.error("--host must be one numeric IP address, not a hostname or range")
    report = {"generated_utc": datetime.now(timezone.utc).isoformat(),
              "host": args.host, "port": args.port, "tcp": probe(args.host, args.port, args.timeout),
              "meaning": "TCP connection only; no ROS, SDK, authentication, or application task is verified."}
    if args.ping:
        if platform.system() != "Linux":
            report["ping"] = {"status": "not-run", "reason": "This optional command uses Linux iputils flags."}
        else:
            try:
                result = subprocess.run(["ping", "-n", "-c", "3", "-W", "1", args.host],
                                        capture_output=True, text=True, timeout=6, check=False)
                report["ping"] = {"exit_code": result.returncode,
                                  "stdout": result.stdout[:5000], "stderr": result.stderr[:1000]}
            except (OSError, subprocess.TimeoutExpired) as error:
                report["ping"] = {"status": "failed", "error": str(error)}
    args.output.parent.mkdir(parents=True, exist_ok=True)
    args.output.write_text(json.dumps(report, indent=2) + "\n", encoding="utf-8")
    print(json.dumps(report, indent=2))
    return 0 if report["tcp"]["connected"] else 2


if __name__ == "__main__":
    sys.exit(main())

import unittest
from analyze_telemetry import audit


def row(t, value=20, unit="C", frame="lab_sensor"):
    return {"stamp_s": str(t), "value": str(value), "unit": unit, "frame_id": frame}


class AuditTests(unittest.TestCase):
    def test_rate(self):
        report, _ = audit([row(0), row(.1), row(.2)])
        self.assertAlmostEqual(report["median_rate_hz"], 10)
    def test_duplicate(self):
        report, _ = audit([row(0), row(0)])
        self.assertEqual(report["rejected_rows"], 1)
    def test_invalid_value(self):
        report, _ = audit([row(0, float("nan"))])
        self.assertEqual(report["accepted_rows"], 0)
    def test_unit_and_frame(self):
        report, _ = audit([row(0, unit="K"), row(.1, frame="other")])
        self.assertEqual(report["rejected_rows"], 2)
    def test_gap(self):
        report, _ = audit([row(0), row(.5)])
        self.assertEqual(report["gaps"][0]["gap_s"], .5)
    def test_exact_boundary(self):
        report, _ = audit([row(0), row(.2), row(.4)])
        self.assertEqual(report["gaps"], [])


if __name__ == "__main__":
    unittest.main()

"""Pure message-validation rules; importable without ROS for offline tests."""
import math


def assess_sample(temperature_c, stamp_ns, now_ns, frame, expected_frame, max_age_ms):
    if not all(math.isfinite(value) for value in (temperature_c, stamp_ns, now_ns, max_age_ms)):
        return "non_finite", None
    if max_age_ms < 0 or stamp_ns < 0 or now_ns < 0:
        return "invalid_time", None
    age_ms = (now_ns - stamp_ns) / 1_000_000
    if frame != expected_frame:
        return "frame_mismatch", age_ms
    if age_ms < 0:
        return "future_stamp", age_ms
    if age_ms > max_age_ms:
        return "stale", age_ms
    return "valid", age_ms

import unittest
from telemetry_rules import assess_sample


class RuleTests(unittest.TestCase):
    def check_reason(self, stamp, now, reason, temperature=20.0, frame="lab_sensor", limit=200.0):
        actual, _ = assess_sample(temperature, stamp, now, frame, "lab_sensor", limit)
        self.assertEqual(actual, reason)
    def test_current(self):
        self.check_reason(900_000_000, 1_000_000_000, "valid")
    def test_boundary(self):
        self.check_reason(800_000_000, 1_000_000_000, "valid")
    def test_stale(self):
        self.check_reason(799_000_000, 1_000_000_000, "stale")
    def test_future(self):
        self.check_reason(1_001_000_000, 1_000_000_000, "future_stamp")
    def test_nan(self):
        self.check_reason(0, 0, "non_finite", temperature=float("nan"))
    def test_wrong_frame(self):
        self.check_reason(0, 0, "frame_mismatch", frame="unknown")
    def test_negative_limit(self):
        self.check_reason(0, 0, "invalid_time", limit=-1)
    def test_zero_age(self):
        self.check_reason(1_000_000_000, 1_000_000_000, "valid", limit=0)


if __name__ == "__main__":
    unittest.main()

"""Analyze G1 recorder output without claiming firmware-specific fault meanings."""
import argparse
import copy
import json
import math
import statistics
from pathlib import Path
from reader_common import fixture
from g1_record import record


def analyze(rows, max_gap=0.1, temperature_warning=70.0):
    problems = []; gaps = []; temperatures = []; previous = None
    counts = set(); records = 0
    for line, row in enumerate(rows, 1):
        records += 1
        t = float(row['received_s'])
        if previous is not None:
            gap = t-previous; gaps.append(gap)
            if gap <= 0: problems.append(dict(line=line, kind='NONMONOTONIC_RECEIVE_TIME'))
            elif gap > max_gap: problems.append(dict(line=line, kind='ARRIVAL_GAP', seconds=gap))
        previous = t
        counts.add(len(row['motors']))
        q = row['quaternion']; norm = math.sqrt(sum(float(v)**2 for v in q))
        if len(q)!=4 or not math.isfinite(norm) or abs(norm-1)>0.05:
            problems.append(dict(line=line, kind='QUATERNION_NORM'))
        for motor in row['motors']:
            if not all(math.isfinite(float(motor[k])) for k in ['q','dq','tau_est','voltage']):
                problems.append(dict(line=line, kind='NONFINITE_MOTOR', index=motor['index']))
            for temp in motor['temperature']:
                if math.isfinite(float(temp)):
                    temperatures.append(float(temp))
                    if temp >= temperature_warning:
                        problems.append(dict(line=line, kind='PROJECT_TEMPERATURE_WARNING', index=motor['index'], value=temp))
            if motor['status']:
                problems.append(dict(line=line, kind='NONZERO_RAW_STATUS', index=motor['index'], raw=motor['status']))
    if not records:
        raise ValueError('No telemetry rows to analyze')
    return dict(records=records, motor_slot_counts=sorted(counts),
                median_arrival_gap_s=statistics.median(gaps) if gaps else None,
                maximum_arrival_gap_s=max(gaps) if gaps else None,
                maximum_temperature=max(temperatures) if temperatures else None,
                thresholds=dict(maximum_gap_s=max_gap, project_temperature_warning=temperature_warning),
                problems=problems,
                limitations=['Arrival gaps include host effects; they do not locate packet loss.',
                             'Temperature threshold is a project warning, not a vendor operating limit.',
                             'HG LowState does not expose a battery SOC field; motor voltage is not SOC.'])


def mock_rows():
    return [record(fixture('g1',i),i*0.02) for i in range(10)]


def self_test():
    rows = mock_rows(); assert not analyze(rows)['problems']
    rows[4]['received_s'] = rows[3]['received_s']
    rows[5]['motors'][0]['temperature'][0] = 90
    rows[6]['quaternion'] = [2,0,0,0]
    kinds={p['kind'] for p in analyze(rows)['problems']}
    assert {'NONMONOTONIC_RECEIVE_TIME','PROJECT_TEMPERATURE_WARNING','QUATERNION_NORM'} <= kinds
    print('PASS: valid fixture plus timestamp, temperature and quaternion failures')


def main():
    p=argparse.ArgumentParser(description=__doc__)
    p.add_argument('--input'); p.add_argument('--mock',action='store_true')
    p.add_argument('--self-test',action='store_true'); p.add_argument('--output',default='g1-health.json')
    p.add_argument('--max-gap',type=float,default=0.1); p.add_argument('--temperature-warning',type=float,default=70)
    a=p.parse_args()
    if a.self_test: self_test();return
    if a.max_gap<=0: p.error('--max-gap must be positive')
    if a.input:
        with open(a.input) as handle: result=analyze((json.loads(x) for x in handle if x.strip()),a.max_gap,a.temperature_warning)
    else: result=analyze(mock_rows(),a.max_gap,a.temperature_warning)
    Path(a.output).write_text(json.dumps(result,indent=2,allow_nan=False)+'\n')
    print(json.dumps({k:v for k,v in result.items() if k!='problems'}));print('Problem records:',len(result['problems']))
if __name__=='__main__':main()

"""Decode G1 remote bytes from HG LowState; this program never acts on buttons."""
import argparse
import json
import math
import struct
from pathlib import Path
from reader_common import add_reader_args,fixture,stream
BUTTONS=['R1','L1','Start','Select','R2','L2','F1','F3','A','B','X','Y','Up','Right','Down','Left']


def decode(raw):
    data=bytes(raw)
    if len(data)!=40:raise ValueError('Expected 40 remote bytes in HG LowState')
    bits=data[2] | (data[3]<<8)
    axes={name:struct.unpack_from('<f',data,offset)[0] for name,offset in [('Lx',4),('Rx',8),('Ry',12),('Ly',20)]}
    if not all(math.isfinite(x) for x in axes.values()):raise ValueError('Nonfinite stick value')
    return {'buttons':[name for bit,name in enumerate(BUTTONS) if bits&(1<<bit)],'axes':axes,'raw_button_bits':bits}


def main():
    p=argparse.ArgumentParser(description=__doc__);add_reader_args(p,'rt/lf/lowstate')
    p.add_argument('--output',default='remote-events.jsonl');a=p.parse_args()
    if a.self_test:
        d=decode(fixture('g1',0).wireless_remote);assert d['buttons']==['R1','A'];assert abs(d['axes']['Ly']+0.2)<1e-6
        try:decode([0]*39)
        except ValueError:pass
        else:raise AssertionError('Short record accepted')
        print('PASS: little-endian axes, button map and length guard');return 0
    stats={};previous=set();count=0
    with Path(a.output).open('w') as handle:
        try:
            for received,message in stream('g1',a,stats):
                d=decode(message.wireless_remote);current=set(d['buttons'])
                d.update(received_s=received,pressed=sorted(current-previous),released=sorted(previous-current))
                handle.write(json.dumps(d,allow_nan=False)+'\n')
                if d['pressed'] or d['released']:print(json.dumps(d))
                previous=current;count+=1
        except KeyboardInterrupt:print('Stopped; reader closed.')
    print(json.dumps(dict(stats,records=count)));return 0 if count else 2
if __name__=='__main__':raise SystemExit(main())

// Original receive-only Go1 telemetry tool. No UDP Send or SetSend calls.
#include <unitree_legged_sdk/comm.h>
#ifdef UNITREE_LIVE
#include <unitree_legged_sdk/udp.h>
#endif
#include <atomic>
#include <chrono>
#include <cmath>
#include <csignal>
#include <cstdlib>
#include <iomanip>
#include <iostream>
#include <stdexcept>
#include <string>
#include <thread>
using namespace UNITREE_LEGGED_SDK;
volatile std::sig_atomic_t stop_requested=0;
void stop_handler(int){stop_requested=1;}

void header(){
  std::cout<<"received_s,mode,soc_percent,current_mA,body_height_m,vx_m_s,vy_m_s,yaw_rad_s";
  for(int i=0;i<12;i++)std::cout<<",q"<<i<<"_rad";
  for(int i=0;i<12;i++)std::cout<<",temperature"<<i;
  for(int i=0;i<10;i++)std::cout<<",cell"<<i<<"_mV";
  std::cout<<"\n";
}
void row(const HighState& s,double elapsed){
  std::cout<<std::fixed<<std::setprecision(6)<<elapsed<<','<<int(s.mode)<<','<<int(s.bms.SOC)<<','<<s.bms.current
    <<','<<s.bodyHeight<<','<<s.velocity[0]<<','<<s.velocity[1]<<','<<s.yawSpeed;
  for(int i=0;i<12;i++)std::cout<<','<<s.motorState[i].q;
  for(int i=0;i<12;i++)std::cout<<','<<int(s.motorState[i].temperature);
  for(auto cell:s.bms.cell_vol)std::cout<<','<<cell;
  std::cout<<'\n';
}
HighState fixture(int n){
  HighState s{};s.mode=0;s.bms.SOC=80;s.bms.current=-1000;s.bodyHeight=0.28f;
  for(int i=0;i<12;i++){s.motorState[i].q=0.02f*std::sin(n*0.02f+i*0.1f);s.motorState[i].temperature=30+i%3;}
  for(auto& cell:s.bms.cell_vol)cell=4000;
  return s;
}
int main(int argc,char** argv){
  try{
    bool live=false,self_test=false;int samples=100,local_port=8090,target_port=8082;double seconds=10;
    std::string address="192.168.123.161";
    for(int i=1;i<argc;i++){
      std::string a=argv[i];auto value=[&](){if(i+1>=argc)throw std::runtime_error("Missing value for "+a);return std::string(argv[++i]);};
      if(a=="--live")live=true;else if(a=="--mock")live=false;else if(a=="--self-test")self_test=true;
      else if(a=="--samples")samples=std::stoi(value());else if(a=="--seconds")seconds=std::stod(value());
      else if(a=="--local-port")local_port=std::stoi(value());else if(a=="--target-port")target_port=std::stoi(value());
      else if(a=="--target-ip")address=value();else throw std::runtime_error("Unknown argument: "+a);
    }
    if(samples<1||samples>1000000||!(seconds>0&&seconds<=3600)||local_port<1||local_port>65535||target_port<1||target_port>65535)
      throw std::runtime_error("Invalid duration, sample count or UDP port");
    if(self_test){auto s=fixture(1);if(s.bms.SOC!=80||s.bms.current!=-1000||s.bms.cell_vol[9]!=4000||s.motorState[11].temperature!=32)throw std::runtime_error("Fixture failed");std::cout<<"PASS: compiled against pinned HighState/BmsState fields; no socket opened\n";return 0;}
    if(!live){header();for(int i=0;i<samples;i++)row(fixture(i),i*0.02);std::cerr<<"Synthetic records: "<<samples<<"\n";return 0;}
#ifndef UNITREE_LIVE
    throw std::runtime_error("This binary contains only fixture mode. Build the Linux live target explicitly.");
#else
    std::signal(SIGINT,stop_handler);std::signal(SIGTERM,stop_handler);
    UDP receiver(static_cast<uint16_t>(local_port),address.c_str(),static_cast<uint16_t>(target_port),
                 sizeof(HighCmd),sizeof(HighState),false,RecvEnum::nonBlock);
    HighState state{};unsigned long long previous=receiver.udpState.RecvCount,records=0;
    auto start=std::chrono::steady_clock::now();header();
    while(!stop_requested){
      double elapsed=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();
      if(elapsed>=seconds)break;
      receiver.Recv();
      if(receiver.udpState.RecvCount>previous){
        previous=receiver.udpState.RecvCount;receiver.GetRecv(state);row(state,elapsed);records++;
      }
      std::this_thread::sleep_for(std::chrono::milliseconds(2));
    }
    std::cerr<<"Received: "<<records<<", receive CRC errors: "<<receiver.udpState.RecvCRCError<<"\n";
    if(!records)std::cerr<<"No telemetry. This tool never sends a command/handshake; the approved stream must already target the configured host/port. Do not substitute a motion example to make it respond.\n";
    return records?0:2;
#endif
  }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 2;}
}

"""Summarize Go1 receive-only CSV battery and thermal observations."""
import argparse
import csv
import json
from pathlib import Path


def summarize(rows,min_soc=20,temperature_warning=70):
    rows=list(rows)
    if not rows:raise ValueError('No telemetry rows to analyze')
    alerts=[];soc=[];currents=[];temperatures=[];spreads=[]
    for n,row in enumerate(rows,1):
        charge=int(row['soc_percent']);soc.append(charge);currents.append(float(row['current_mA'])/1000)
        if not 0<=charge<=100:alerts.append(dict(row=n,kind='INVALID_SOC',value=charge))
        elif charge<min_soc:alerts.append(dict(row=n,kind='PROJECT_LOW_SOC',value=charge))
        temps=[int(row[f'temperature{i}']) for i in range(12)];temperatures+=temps
        if max(temps)>=temperature_warning:alerts.append(dict(row=n,kind='PROJECT_TEMPERATURE_WARNING',value=max(temps)))
        cells=[int(row[f'cell{i}_mV']) for i in range(10)]
        # Zero/missing channels are unavailable, not zero-volt measured cells.
        valid=[v for v in cells if v>0]
        spreads.append(max(valid)-min(valid) if len(valid)>1 else None)
    return dict(records=len(rows),minimum_soc_percent=min(soc),maximum_abs_current_A=max(abs(x) for x in currents),
                signed_current_A=dict(minimum=min(currents),maximum=max(currents)),maximum_temperature=max(temperatures),
                maximum_available_cell_spread_mV=max((x for x in spreads if x is not None),default=None),alerts=alerts,
                note='Thresholds are project review flags, not vendor charge/discharge limits. Current sign is preserved without inferring firmware sign semantics.')


def fixture():
    d=dict(soc_percent='80',current_mA='-1000')
    d.update({f'temperature{i}':'30' for i in range(12)})
    d.update({f'cell{i}_mV':'4000' for i in range(10)})
    return d


def main():
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('--input');p.add_argument('--mock',action='store_true')
    p.add_argument('--self-test',action='store_true');p.add_argument('--min-soc',type=int,default=20)
    p.add_argument('--temperature-warning',type=int,default=70);p.add_argument('--output',default='go1-health.json');a=p.parse_args()
    if a.self_test:
        d=fixture();assert summarize([d])['maximum_abs_current_A']==1
        d['soc_percent']='10';d['temperature0']='80';assert len(summarize([d])['alerts'])==2
        d['cell0_mV']='0';assert summarize([d])['maximum_available_cell_spread_mV']==0
        print('PASS: mA/A conversion, project thresholds and unavailable cell handling');return
    if a.input:
        with open(a.input,newline='') as h:result=summarize(csv.DictReader(h),a.min_soc,a.temperature_warning)
    else:result=summarize([fixture()],a.min_soc,a.temperature_warning)
    Path(a.output).write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result,indent=2))
if __name__=='__main__':main()

