"""Read Linux USB descriptors and compare snapshots; no vendor protocol guessed."""
import argparse
import json
from pathlib import Path


def inventory(root):
    devices=[]
    for node in sorted(root.iterdir()):
        if not (node/'idVendor').exists():continue
        def read(name):
            try:return (node/name).read_text().strip()
            except (OSError,UnicodeError):return None
        devices.append(dict(path=node.name,vendor_id=read('idVendor'),product_id=read('idProduct'),
                            manufacturer=read('manufacturer'),product=read('product'),
                            bus=read('busnum'),address=read('devnum')))
    return devices


def difference(before,after):
    key=lambda x:(x['path'],x['vendor_id'],x['product_id'])
    old={key(x) for x in before};new={key(x) for x in after}
    return dict(added=[x for x in after if key(x) not in old],removed=[x for x in before if key(x) not in new])


def main():
    p=argparse.ArgumentParser(description=__doc__)
    p.add_argument('--live',action='store_true');p.add_argument('--mock',action='store_true')
    p.add_argument('--before');p.add_argument('--output',default='usb-snapshot.json')
    p.add_argument('--self-test',action='store_true');a=p.parse_args()
    fake=[dict(path='fixture-1',vendor_id='ffff',product_id='0010',manufacturer='SYNTHETIC',product='Test device',bus='0',address='1')]
    if a.self_test:
        assert difference([],fake)['added']==fake and difference(fake,[])['removed']==fake
        assert difference(fake,fake)==dict(added=[],removed=[])
        print('PASS: added, removed and unchanged USB snapshots');return
    if a.live:
        root=Path('/sys/bus/usb/devices')
        if not root.is_dir():p.error('Live inventory requires Linux USB sysfs; use --mock elsewhere')
        devices=inventory(root)
    else:devices=fake
    result=dict(source='linux-sysfs' if a.live else 'synthetic',devices=devices,
                note='An added USB device is a candidate, not verified Dex5 identity. No control transfer or motor command was sent.')
    if a.before:result['difference']=difference(json.loads(Path(a.before).read_text())['devices'],devices)
    Path(a.output).write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result,indent=2))
if __name__=='__main__':main()

#!/usr/bin/env python3
"""Save one compressed X2 camera frame and metadata; never subscribes raw 80MB/s image."""
import argparse
import json
from pathlib import Path
import time

def save_frame(data,fmt,stamp,frame,prefix,mock=False):
    # Decide by bytes, not an untrusted filename or format string.
    if data.startswith(b'\xff\xd8\xff'):extension='.jpg'
    elif data.startswith(b'\x89PNG\r\n\x1a\n'):extension='.png'
    else:raise ValueError('Expected JPEG or PNG compressed bytes, got '+fmt)
    path=Path(str(prefix)+extension);path.write_bytes(data)
    metadata={'mock':mock,'file':str(path),'bytes':len(data),'format':fmt,'frame_id':frame,
              'header_stamp_s':stamp,'received_unix_s':time.time(),
              'scope':'One RGB image; no depth registration or metric localization is implied.'}
    Path(str(prefix)+'.json').write_text(json.dumps(metadata,indent=2))
    print(json.dumps(metadata));return metadata

def main():
    p=argparse.ArgumentParser();p.add_argument('--mock',action='store_true')
    p.add_argument('--topic',default='/aima/hal/sensor/rgbd_head_front/rgb_image/compressed')
    p.add_argument('--prefix',default='x2-camera');p.add_argument('--timeout',type=float,default=10)
    a=p.parse_args()
    if not 0<a.timeout<=60:p.error('--timeout must be in (0,60]')
    if a.mock:
        import base64
        # Original synthetic single transparent pixel fixture; no camera data.
        data=base64.b64decode('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII=')
        out=save_frame(data,'png',0,'synthetic',a.prefix,True)
        assert Path(out['file']).read_bytes()==data
        return
    import rclpy
    from rclpy.node import Node
    from rclpy.qos import QoSProfile,ReliabilityPolicy,DurabilityPolicy
    from sensor_msgs.msg import CompressedImage
    rclpy.init();node=Node('course_x2_camera_snapshot');frames=[]
    qos=QoSProfile(depth=1,reliability=ReliabilityPolicy.BEST_EFFORT,durability=DurabilityPolicy.VOLATILE)
    def receive(msg):
        if not frames:frames.append(msg)
    node.create_subscription(CompressedImage,a.topic,receive,qos)
    end=time.monotonic()+a.timeout
    try:
        while rclpy.ok() and not frames and time.monotonic()<end:rclpy.spin_once(node,timeout_sec=.1)
        if not frames:raise TimeoutError('No compressed frame; EDU lacks the Ultra camera package')
        m=frames[0];save_frame(bytes(m.data),m.format,m.header.stamp.sec+m.header.stamp.nanosec/1e9,m.header.frame_id,a.prefix)
    finally:node.destroy_node();rclpy.try_shutdown()
if __name__=='__main__':
    try:main()
    except KeyboardInterrupt:raise SystemExit(130)

#!/usr/bin/env python3
"""X2 SIMULATION ONLY. Defaults to a mock command trace; no hardware option exists."""
import argparse
import json
import os
from pathlib import Path
import time
import uuid


def plan(speed, seconds):
    if not 0.1<=speed<=0.2 or not 0<seconds<=2:
        raise ValueError('Course simulation limits: speed 0.1..0.2 m/s; duration (0,2] s')
    return [speed]*max(1,round(seconds*50)) + [0.0]*10


def main():
    p=argparse.ArgumentParser();p.add_argument('--sim',action='store_true')
    p.add_argument('--speed',type=float,default=.15);p.add_argument('--seconds',type=float,default=1)
    p.add_argument('--output',default='x2-sim-commands.json');a=p.parse_args();values=plan(a.speed,a.seconds)
    if not a.sim:
        out={'mock':True,'rate_hz':50,'forward_velocity_mps':values,'note':'No ROS imports or robot connection'}
        assert values[-10:]==[0.0]*10
        Path(a.output).write_text(json.dumps(out,indent=2));print(json.dumps({'mock':True,'commands':len(values),'last_command':values[-1]}));return
    if os.environ.get('ROS_DOMAIN_ID')!='77' or os.environ.get('ROS_LOCALHOST_ONLY')!='1':
        raise SystemExit('Refusing: set ROS_DOMAIN_ID=77 and ROS_LOCALHOST_ONLY=1 on this client AND isolated simulator')
    import rclpy
    from rclpy.node import Node
    from rclpy.qos import QoSProfile,ReliabilityPolicy,DurabilityPolicy
    from aimdk_msgs.msg import CommonRequest,McLocomotionVelocity,McInputAction,McInputSource
    from aimdk_msgs.srv import GetMcAction,SetMcInputSource
    rclpy.init();node=Node('course_x2_sim_walk');source='sdk_course_'+uuid.uuid4().hex[:8];events=[];registered=False
    qos=QoSProfile(depth=1,reliability=ReliabilityPolicy.BEST_EFFORT,durability=DurabilityPolicy.VOLATILE)
    pub=node.create_publisher(McLocomotionVelocity,'/aima/mc/locomotion/velocity',qos)
    def call(kind,name,request):
        client=node.create_client(kind,name)
        try:
            if not client.wait_for_service(timeout_sec=3):raise TimeoutError(name+' unavailable')
            f=client.call_async(request);rclpy.spin_until_future_complete(node,f,timeout_sec=3)
            if not f.done():f.cancel();raise TimeoutError(name+' response timeout')
            result=f.result()
            if result is None:raise RuntimeError(str(f.exception()))
            return result
        finally:node.destroy_client(client)
    def source_operation(value):
        req=SetMcInputSource.Request();req.request=CommonRequest();req.request.header.stamp=node.get_clock().now().to_msg()
        req.action=McInputAction();req.action.value=value
        req.input_source=McInputSource();req.input_source.name=source;req.input_source.priority=20;req.input_source.timeout=1000
        res=call(SetMcInputSource,'/aimdk_5Fmsgs/srv/SetMcInputSource',req)
        if res.response.header.code!=0:raise RuntimeError('Input-source request rejected: '+str(res.response.header.code))
    def send(v):
        msg=McLocomotionVelocity();msg.header.stamp=node.get_clock().now().to_msg();msg.source=source
        msg.forward_velocity=float(v);msg.lateral_velocity=0.;msg.angular_velocity=0.;pub.publish(msg)
        events.append({'monotonic_s':time.monotonic(),'forward_mps':v})
    try:
        query=GetMcAction.Request();query.request=CommonRequest();query.request.header.stamp=node.get_clock().now().to_msg()
        response=call(GetMcAction,'/aimdk_5Fmsgs/srv/GetMcAction',query)
        if response.info.action_desc not in ('STAND_DEFAULT','LOCOMOTION_DEFAULT'):
            raise RuntimeError('Prepare the isolated simulator in STAND_DEFAULT first; this script does not change modes')
        source_operation(1001);registered=True
        deadline=time.monotonic()+3
        while pub.get_subscription_count()==0 and time.monotonic()<deadline:rclpy.spin_once(node,timeout_sec=.1)
        if pub.get_subscription_count()==0:raise RuntimeError('No simulated velocity subscriber')
        end=time.monotonic()+a.seconds;next_tick=time.monotonic()
        while rclpy.ok() and time.monotonic()<end:
            send(a.speed);next_tick+=.02;rclpy.spin_once(node,timeout_sec=0);time.sleep(max(0,next_tick-time.monotonic()))
    except KeyboardInterrupt:pass
    finally:
        if registered:
            for _ in range(10):send(0.);rclpy.spin_once(node,timeout_sec=0);time.sleep(.02)
            try:source_operation(1003)
            except Exception as e:print('Custom source cleanup failed:',e)
        Path(a.output).write_text(json.dumps({'mock':False,'simulation_only':True,'source':source,'events':events},indent=2))
        node.destroy_node();rclpy.try_shutdown()
if __name__=='__main__':main()

#include "d1_transport.hpp"
#include <chrono>
#include <cmath>
#include <csignal>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <stdexcept>
#include <thread>
using Clock=std::chrono::steady_clock;
static volatile std::sig_atomic_t running=1;
void stop(int){running=0;}
void check_vector(const std::vector<float>& v,std::size_t n){
    if(v.size()!=n)throw std::runtime_error("Unexpected vector length");
    for(float x:v)if(!std::isfinite(x))throw std::runtime_error("Nonfinite telemetry");
}
int main(int argc,char** argv){
    try{
        std::string local,robot,output="d1-telemetry.csv";double seconds=5;int port=43988;bool ack=false;
        for(int i=1;i<argc;++i){std::string k=argv[i];
            if(k=="--ack-sdk-ownership"){ack=true;continue;}
            if(i+1>=argc)throw std::runtime_error("Missing value for "+k);
            std::string v=argv[++i];
            if(k=="--local-ip")local=v;else if(k=="--robot-ip")robot=v;
            else if(k=="--output")output=v;else if(k=="--seconds")seconds=std::stod(v);
            else if(k=="--local-port")port=std::stoi(v);else throw std::runtime_error("Unknown option "+k);
        }
        if(!(seconds>0&&seconds<=300)||port<1024||port>65535)throw std::runtime_error("Invalid duration or port");
#ifdef D1_MOCK
        local="127.0.0.1";robot="127.0.0.1";std::cerr<<"SYNTHETIC SDK MOCK; no hardware\n";(void)ack;
#else
        if(local.empty()||robot.empty()||!ack)throw std::runtime_error("Provide --local-ip, --robot-ip and --ack-sdk-ownership after reviewing the D1 ownership procedure");
#endif
        std::ofstream csv(output);if(!csv)throw std::runtime_error("Cannot open output");
        csv<<"host_elapsed_s,battery_percent,last_ctrl_mode,qw,qx,qy,qz,gx,gy,gz,ax,ay,az,body_vx,body_vy,body_vz,FR_abad,FL_abad,RR_abad,RL_abad,FR_hip,FL_hip,RR_hip,RL_hip,FR_knee,FL_knee,RR_knee,RL_knee\n";
        csv<<std::setprecision(9);std::signal(SIGINT,stop);std::signal(SIGTERM,stop);
        mc_sdk::zsl_1::HighLevel sdk;sdk.initRobot(local,port,robot);
        const auto start=Clock::now();auto tick=start;unsigned count=0;
        while(running&&std::chrono::duration<double>(Clock::now()-start).count()<seconds){
            if(!sdk.checkConnect())throw std::runtime_error("SDK connection lost");
            const auto q=sdk.getQuaternion(),g=sdk.getBodyGyro(),a=sdk.getBodyAcc(),v=sdk.getBodyVelocity();
            const auto abad=sdk.getLegAbadJoint(),hip=sdk.getLegHipJoint(),knee=sdk.getLegKneeJoint();
            check_vector(q,4);for(const auto* x:{&g,&a,&v})check_vector(*x,3);for(const auto* x:{&abad,&hip,&knee})check_vector(*x,4);
            csv<<std::chrono::duration<double>(Clock::now()-start).count()<<','<<sdk.getBatteryPower()<<','<<sdk.getCurrentCtrlmode();
            for(const auto* x:{&q,&g,&a,&v,&abad,&hip,&knee})for(float value:*x)csv<<','<<value;
            csv<<'\n';++count;tick+=std::chrono::milliseconds(20);std::this_thread::sleep_until(tick);
        }
        std::cout<<"Saved "<<count<<" rows to "<<output<<". Timestamps are host acquisition times, not guaranteed sensor times.\n";
        return count?0:2;
    }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}
}

