#!/usr/bin/env python3
"""Run only vendor read test 1, then summarize its version-1 report."""
import argparse
import json
from pathlib import Path
import signal
import subprocess
import sys
import tempfile


def summarize(payload):
    if payload.get('schema_version')!=1:raise ValueError('Unexpected vendor report schema')
    reports=payload.get('reports',[])
    if not reports:raise ValueError('No measurement reports returned')
    rows=[]
    for r in reports:
        total,good,bad=r['total_tests'],r['successful_tests'],r['failed_tests']
        if total!=good+bad or total<=0:raise ValueError('Inconsistent attempt accounting')
        rows.append({'operation':r['function_name'],'attempts':total,'successes':good,'failures':bad,
          'success_fraction':good/total,'achieved_hz':r['actual_frequency_hz'],'requested_hz':r['target_frequency_hz'],
          'p99_latency_ms':r['p99_latency_ms'],'worst_latency_ms':r['max_latency_ms'],
          'connection':r['connection']})
    return rows


def main():
    p=argparse.ArgumentParser();p.add_argument('--device',action='store_true');p.add_argument('--sdk-dir',type=Path)
    p.add_argument('--duration',type=float,default=10);p.add_argument('--target-hz',type=float,default=100)
    p.add_argument('--output',type=Path,default=Path('revo-benchmark.json'));a=p.parse_args()
    if not 0<a.duration<=120 or not 0<a.target_hz<=500:p.error('Duration (0,120] and rate (0,500] required')
    if not a.device:
        payload={'schema_version':1,'reports':[{'function_name':'get_motor_status','total_tests':100,'successful_tests':98,'failed_tests':2,
         'actual_frequency_hz':98.,'target_frequency_hz':100.,'p99_latency_ms':14.,'max_latency_ms':20.,
         'connection':{'protocol':'SYNTHETIC','port_name':'none'}}]}
        a.output.write_text(json.dumps(payload,indent=2))
    else:
        if a.sdk_dir is None:p.error('--device requires --sdk-dir')
        program=a.sdk_dir.resolve()/'python/demo/comm_frequency_test.py'
        if not program.is_file():raise SystemExit('Pinned vendor benchmark not found: '+str(program))
        # A unique report path prevents a no-device run from reusing yesterday's JSON.
        with tempfile.TemporaryDirectory(prefix='revo-read-') as temporary:
            report_path=Path(temporary)/'vendor-report.json'
            command=[sys.executable,str(program),'1','--duration',str(a.duration),'--target-hz',str(a.target_hz),'--output',str(report_path)]
            # Hard-code test 1. No passthrough argument can select a moving test.
            child=subprocess.Popen(command)
            try:
                try:code=child.wait(timeout=a.duration+30)
                except (subprocess.TimeoutExpired,KeyboardInterrupt):
                    child.send_signal(signal.SIGINT)
                    try:child.wait(timeout=3)
                    except subprocess.TimeoutExpired:child.kill();child.wait()
                    raise SystemExit('Read-only benchmark interrupted or timed out')
                if code:raise SystemExit('Vendor read benchmark failed: '+str(code))
            finally:
                if child.poll() is None:child.terminate();child.wait(timeout=3)
            if not report_path.is_file():raise SystemExit('Vendor returned no new report; check device discovery')
            payload=json.loads(report_path.read_text())
            summarize(payload)  # Validate before replacing a prior successful report.
            a.output.write_text(json.dumps(payload,indent=2))
    summary={'mock':not a.device,'measurements':summarize(payload)}
    Path(str(a.output)+'.summary.json').write_text(json.dumps(summary,indent=2));print(json.dumps(summary,indent=2))
    if not a.device:assert summary['measurements'][0]['success_fraction']==.98
if __name__=='__main__':main()

#!/usr/bin/env python3
"""Bounded read-only JointState recorder, preserving unavailable fields as blanks."""
import argparse
import csv
import json
import math
from pathlib import Path
import time

FIELDS=['host_monotonic_s','header_stamp_s','joint','position_rad','velocity_rad_s','effort']
def expand(names,positions,velocities,efforts,host,stamp):
    n=len(names)
    if not n or len(set(names))!=n:raise ValueError('Empty or duplicate joint names')
    if any(len(x) not in (0,n) for x in (positions,velocities,efforts)):raise ValueError('JointState lengths disagree')
    for values in (positions,velocities,efforts):
        if any(not math.isfinite(x) for x in values):raise ValueError('Nonfinite joint value')
    return [dict(zip(FIELDS,[host,stamp,name,positions[i] if positions else '',velocities[i] if velocities else '',efforts[i] if efforts else ''])) for i,name in enumerate(names)]

def main():
    p=argparse.ArgumentParser();p.add_argument('--mock',action='store_true');p.add_argument('--seconds',type=float,default=10)
    p.add_argument('--topic',default='/joint_states');p.add_argument('--contains',default='right_')
    p.add_argument('--output',default='revo-joints.csv');a=p.parse_args()
    if not 0<a.seconds<=300:p.error('--seconds must be in (0,300]')
    rows=0;messages=0;rejected=0;observed=set()
    with Path(a.output).open('w',newline='') as f:
        writer=csv.DictWriter(f,fieldnames=FIELDS);writer.writeheader()
        def record(names,pos,vel,eff,host,stamp):
            nonlocal rows,messages,rejected
            try:data=expand(names,pos,vel,eff,host,stamp)
            except ValueError as error:rejected+=1;print('Rejected:',error);return
            messages+=1
            for r in data:
                if a.contains in r['joint']:writer.writerow(r);rows+=1;observed.add(r['joint'])
        if a.mock:
            for i in range(10):record(['right_index_proximal_joint','left_index_proximal_joint'],[i*.01,0],[],[],i*.01,i*.01)
            assert rows==10
            try:expand(['same','same'],[0,0],[],[],0,0)
            except ValueError:pass
            else:raise AssertionError('Duplicate joints not rejected')
        else:
            import rclpy
            from rclpy.node import Node
            from rclpy.qos import QoSProfile,ReliabilityPolicy,DurabilityPolicy
            from sensor_msgs.msg import JointState
            rclpy.init();node=Node('course_revo_joint_csv')
            qos=QoSProfile(depth=100,reliability=ReliabilityPolicy.BEST_EFFORT,durability=DurabilityPolicy.VOLATILE)
            def receive(m):record(list(m.name),list(m.position),list(m.velocity),list(m.effort),time.monotonic(),m.header.stamp.sec+m.header.stamp.nanosec/1e9)
            node.create_subscription(JointState,a.topic,receive,qos);end=time.monotonic()+a.seconds
            try:
                while rclpy.ok() and time.monotonic()<end:rclpy.spin_once(node,timeout_sec=.1)
            except KeyboardInterrupt:pass
            finally:node.destroy_node();rclpy.try_shutdown()
    result={'mock':a.mock,'rows':rows,'messages':messages,'rejected':rejected,'joints':sorted(observed),
            'meaning':'Blank fields are unavailable, not physical zero. Effort semantics come from the active driver.'}
    Path(a.output+'.json').write_text(json.dumps(result,indent=2));print(json.dumps(result,indent=2))
    if rows==0:raise SystemExit('No selected joint rows; inspect actual names and --contains filter')
if __name__=='__main__':main()

#!/usr/bin/env python3
"""Revo2 FakeSystem-only action client; default writes a trajectory plan offline."""
import argparse
import json
import math
import os
from pathlib import Path
import time
NAMES=['right_thumb_proximal_joint','right_thumb_metacarpal_joint','right_index_proximal_joint',
       'right_middle_proximal_joint','right_ring_proximal_joint','right_pinky_proximal_joint']
POSE=[.2,.05,.3,.3,.3,.3]

def ensure_fake(components):
    if not components:raise ValueError('No hardware components discovered')
    for component in components:
        plugin=component.get('class_type','')
        if plugin not in ('mock_components/GenericSystem','fake_components/GenericSystem'):
            raise ValueError('Refusing non-FakeSystem component: '+plugin)

def main():
    p=argparse.ArgumentParser();p.add_argument('--sim',action='store_true')
    p.add_argument('--manager',default='/controller_manager');p.add_argument('--joint-topic',default='/joint_states')
    p.add_argument('--action',default='/right_revo2_hand_controller/follow_joint_trajectory')
    a=p.parse_args()
    if not a.sim:
        ensure_fake([{'class_type':'mock_components/GenericSystem'}])
        try:ensure_fake([{'class_type':'brainco_hand_driver/BrainCoHandHardware'}])
        except ValueError:pass
        else:raise AssertionError('Real driver was accepted')
        Path('revo2-plan.json').write_text(json.dumps({'mock':True,'joint_names':NAMES,'partial_pose':POSE,'return_pose':[0.]*6},indent=2))
        print('Wrote revo2-plan.json; non-FakeSystem rejection test passed');return
    if os.environ.get('ROS_DOMAIN_ID')!='78' or os.environ.get('ROS_LOCALHOST_ONLY')!='1':
        raise SystemExit('Refusing: set domain 78 and ROS_LOCALHOST_ONLY=1 on this client and FakeSystem launch')
    import rclpy
    from rclpy.node import Node
    from rclpy.action import ActionClient
    from rclpy.qos import qos_profile_sensor_data
    from controller_manager_msgs.srv import ListHardwareComponents
    from control_msgs.action import FollowJointTrajectory
    from trajectory_msgs.msg import JointTrajectoryPoint
    from sensor_msgs.msg import JointState
    rclpy.init();node=Node('course_revo_fake_trajectory');goal_handle=None;finished=False
    def wait(future,seconds):
        rclpy.spin_until_future_complete(node,future,timeout_sec=seconds)
        if not future.done():raise TimeoutError('ROS operation timed out')
        value=future.result()
        if value is None:raise RuntimeError(str(future.exception()))
        return value
    try:
        service=node.create_client(ListHardwareComponents,a.manager.rstrip('/')+'/list_hardware_components')
        if not service.wait_for_service(timeout_sec=5):raise TimeoutError('Controller manager unavailable')
        response=wait(service.call_async(ListHardwareComponents.Request()),5)
        ensure_fake([{'class_type':c.class_type} for c in response.component])
        states={}
        def receive(m):
            if len(m.name)==len(m.position):states.update(zip(m.name,m.position))
        node.create_subscription(JointState,a.joint_topic,receive,qos_profile_sensor_data)
        end=time.monotonic()+5
        while not all(n in states for n in NAMES) and time.monotonic()<end:rclpy.spin_once(node,timeout_sec=.1)
        if not all(n in states for n in NAMES):raise RuntimeError('Required right-hand joints not observed')
        if not all(math.isfinite(states[n]) for n in NAMES):raise RuntimeError('Nonfinite simulated joint state')
        client=ActionClient(node,FollowJointTrajectory,a.action)
        if not client.wait_for_server(timeout_sec=5):raise TimeoutError('Trajectory action unavailable')
        goal=FollowJointTrajectory.Goal();goal.trajectory.joint_names=NAMES
        for seconds,positions in ((1,[states[n] for n in NAMES]),(3,POSE),(5,[0.]*6)):
            pt=JointTrajectoryPoint();pt.positions=positions;pt.time_from_start.sec=seconds;goal.trajectory.points.append(pt)
        goal_handle=wait(client.send_goal_async(goal),5)
        if not goal_handle.accepted:raise RuntimeError('Trajectory rejected')
        result=wait(goal_handle.get_result_async(),12);finished=True
        if result.result.error_code!=0:raise RuntimeError('Controller error: '+str(result.result.error_code)+' '+result.result.error_string)
        Path('revo2-execution.json').write_text(json.dumps({'simulation_only':True,'action_status':result.status,'controller_error_code':result.result.error_code,'joint_names':NAMES},indent=2))
        print('FakeSystem trajectory completed; wrote revo2-execution.json')
    finally:
        if goal_handle is not None and goal_handle.accepted and not finished:
            try:wait(goal_handle.cancel_goal_async(),2)
            except Exception as error:print('Simulation cancellation failed:',error)
        node.destroy_node();rclpy.try_shutdown()
if __name__=='__main__':
    try:main()
    except KeyboardInterrupt:raise SystemExit(130)

#!/usr/bin/env python3
"""Inspect an AgiBot World proprio_stats.h5; --demo creates original synthetic data."""
import argparse
import csv
import json
from pathlib import Path
import h5py
import numpy as np


def create_demo(path):
    n=121;t=np.arange(n)/30
    action=np.stack([.2*np.sin(t+i*.1) for i in range(14)],axis=1)
    with h5py.File(path,'w') as f:
        f.attrs['course_synthetic_fixture']=True
        f.create_dataset('timestamp',data=np.arange(n,dtype=np.int64)*33333333)
        f.create_dataset('state/joint/position',data=action*.9)
        f.create_dataset('action/joint/position',data=action)


def inspect(path,out):
    with h5py.File(path,'r') as f:
        paths=('timestamp','state/joint/position','action/joint/position')
        missing=[p for p in paths if p not in f]
        if missing:raise ValueError('Missing datasets: '+', '.join(missing))
        raw_time=np.asarray(f['timestamp'])
        state=np.asarray(f['state/joint/position']);action=np.asarray(f['action/joint/position'])
        synthetic=bool(f.attrs.get('course_synthetic_fixture',False))
    if raw_time.ndim!=1 or len(raw_time)<2:raise ValueError('Expected at least two timestamps')
    if raw_time.dtype.kind not in 'iu' or np.any(raw_time>np.iinfo(np.int64).max):raise ValueError('Expected int64-compatible nanosecond timestamps')
    stamps=raw_time.astype(np.int64);gaps=np.diff(stamps)
    if np.any(gaps<=0):raise ValueError('Nonmonotonic or duplicate timestamps')
    if state.shape!=(len(stamps),14) or action.shape!=state.shape:raise ValueError('Expected [N,14] arm state/action arrays; choose the correct dataset schema')
    if not np.isfinite(state).all() or not np.isfinite(action).all():raise ValueError('Nonfinite joint values')
    elapsed=(stamps-stamps[0])/1e9
    with Path(str(out)+'.csv').open('w',newline='') as f:
        writer=csv.writer(f);writer.writerow(['elapsed_s']+[f'state_joint_{i:02d}' for i in range(14)]+[f'action_joint_{i:02d}' for i in range(14)])
        for t,s,a in zip(elapsed,state,action):writer.writerow([t,*s,*a])
    result={'file':str(path),'synthetic':synthetic,'samples':len(stamps),'duration_s':float(elapsed[-1]),
       'median_period_ms':float(np.median(gaps)/1e6),'max_gap_ms':float(gaps.max()/1e6),
       'per_joint_state_action_rmse_rad':np.sqrt(np.mean((state-action)**2,axis=0)).tolist(),
       'joint_order':'Dataset arm slots 0..6 left, 7..13 right; these are array labels, not a hardware SDK mapping.',
       'interpretation':'State-action disagreement is a tracking/data diagnostic, not a learned policy score.'}
    Path(str(out)+'.json').write_text(json.dumps(result,indent=2));print(json.dumps(result,indent=2));return result


def main():
    p=argparse.ArgumentParser();p.add_argument('--demo',action='store_true');p.add_argument('--file',type=Path)
    p.add_argument('--out',type=Path,default=Path('episode-report'));a=p.parse_args()
    if a.demo:
        a.file=Path('synthetic-episode.h5');create_demo(a.file)
    if a.file is None:p.error('Choose --demo or --file pointing to your authorized proprio_stats.h5')
    report=inspect(a.file,a.out)
    if a.demo:
        assert report['samples']==121 and report['synthetic']
        broken=Path('synthetic-broken-time.h5');create_demo(broken)
        with h5py.File(broken,'r+') as f:f['timestamp'][2]=f['timestamp'][1]
        try:inspect(broken,Path('should-not-exist'))
        except ValueError as error:assert 'timestamps' in str(error)
        else:raise AssertionError('Duplicate timestamp was accepted')
        print('Synthetic normal and invalid-time checks passed')
if __name__=='__main__':main()

#!/usr/bin/env python3
"""GO-1 inference to an output file only. No robot SDK, sockets or command publisher."""
import argparse
import json
from pathlib import Path
import sys
import time
import numpy as np


def make_fixture(path,dim=16):
    y,x=np.indices((48,64));image=np.stack([x*4,y*5,(x+y)*2],axis=-1).astype(np.uint8)
    np.savez_compressed(path,top=image,right=image[:,::-1].copy(),left=image[::-1].copy(),
                        state=np.linspace(-.1,.1,dim,dtype=np.float32),ctrl_freqs=np.array([30],dtype=np.float32))


def load_observation(path,dim,instruction):
    with np.load(path,allow_pickle=False) as data:
        payload={name:data[name].copy() for name in ('top','right','left','state','ctrl_freqs')}
    for name in ('top','right','left'):
        im=payload[name]
        if im.ndim!=3 or im.shape[2]!=3 or im.dtype!=np.uint8:raise ValueError(name+' must be uint8 HxWx3 RGB')
    if payload['state'].shape!=(dim,) or not np.isfinite(payload['state']).all():raise ValueError('Wrong or nonfinite state vector')
    if payload['ctrl_freqs'].shape!=(1,) or not np.isfinite(payload['ctrl_freqs']).all() or payload['ctrl_freqs'][0]<=0:raise ValueError('ctrl_freqs must be one positive finite value')
    if not instruction.strip():raise ValueError('Instruction cannot be empty')
    payload['state']=payload['state'].astype(np.float32);payload['ctrl_freqs']=payload['ctrl_freqs'].astype(np.float32)
    payload['instruction']=instruction
    return payload


def main():
    p=argparse.ArgumentParser();p.add_argument('--demo',action='store_true');p.add_argument('--input',type=Path)
    p.add_argument('--repo',type=Path);p.add_argument('--checkpoint',type=Path);p.add_argument('--statistics',type=Path)
    p.add_argument('--instruction',default='place the object in the container')
    p.add_argument('--output',type=Path,default=Path('go1-actions.npy'));a=p.parse_args()
    if a.demo:
        a.input=Path('synthetic-observation.npz');make_fixture(a.input);dim=16;action_dim=16;chunk=30
    else:
        if any(v is None for v in (a.input,a.repo,a.checkpoint)):p.error('Real inference requires --input, --repo and --checkpoint local paths')
        config=json.loads((a.checkpoint/'config.json').read_text())
        action_config=config['action_config'];dim=int(action_config['state_dim']);action_dim=int(action_config['action_dim']);chunk=int(config['action_chunk_size'])
        if config.get('norm',False) and a.statistics is None:p.error('This checkpoint requires its matching --statistics JSON')
    payload=load_observation(a.input,dim,a.instruction);start=time.monotonic()
    if a.demo:
        # Deterministic artificial output exercises file handling, NOT a GO-1 prediction.
        actions=np.linspace(0,.02,chunk,dtype=np.float32)[:,None]*np.ones((1,action_dim),dtype=np.float32)
    else:
        sys.path.insert(0,str(a.repo.resolve()))
        from evaluate.deploy import GO1Infer
        model=GO1Infer(model_path=str(a.checkpoint),data_stats_path=str(a.statistics) if a.statistics else None)
        actions=np.asarray(model.inference(payload))
    if actions.shape!=(chunk,action_dim) or not np.isfinite(actions).all():raise ValueError('Unexpected action chunk; nothing written')
    np.save(a.output,actions,allow_pickle=False)
    metadata={'demo':a.demo,'checkpoint':str(a.checkpoint) if a.checkpoint else None,'input':str(a.input),
              'output':str(a.output),'shape':list(actions.shape),'elapsed_including_load_s':time.monotonic()-start,
              'control_hz':float(payload['ctrl_freqs'][0]),'horizon_s':chunk/float(payload['ctrl_freqs'][0]),
              'execution':'Output file only; no action sent to hardware'}
    Path(str(a.output)+'.json').write_text(json.dumps(metadata,indent=2));print(json.dumps(metadata,indent=2))
    if a.demo:assert actions.shape==(30,16) and abs(metadata['horizon_s']-1)<1e-9
if __name__=='__main__':main()

#!/usr/bin/env python3
"""Analyze an action NPY and optional aligned reference; creates CSV+SVG, never commands."""
import argparse
import csv
import json
from pathlib import Path
import numpy as np


def analyze(actions,hz):
    if actions.ndim!=2 or min(actions.shape)<1 or not np.isfinite(actions).all():raise ValueError('Expected finite [time,action] array')
    if not np.isfinite(hz) or hz<=0:raise ValueError('Positive finite Hz required')
    differences=np.diff(actions,axis=0)
    return {'steps':int(actions.shape[0]),'dimensions':int(actions.shape[1]),'horizon_s':actions.shape[0]/hz,
       'minimum':actions.min(axis=0).tolist(),'maximum':actions.max(axis=0).tolist(),
       'max_adjacent_change':np.max(np.abs(differences),axis=0).tolist() if len(differences) else [0.]*actions.shape[1]}


def plot_svg(actions,hz,out):
    width,height=960,340;left,right,top,bottom=60,920,35,280
    selected=actions[:,:min(6,actions.shape[1])];lo,hi=float(selected.min()),float(selected.max())
    if hi==lo:lo-=.5;hi+=.5
    colors=['#157f9f','#cc5a34','#668c36','#9559a8','#c18d23','#365cb1']
    pieces=[f'<svg xmlns="http://www.w3.org/2000/svg" width="{width}" height="{height}" viewBox="0 0 {width} {height}">',
      '<rect width="100%" height="100%" fill="white"/>',
      '<text x="60" y="22" font-family="sans-serif" font-size="16">Action chunk: first six dimensions (checkpoint units)</text>',
      f'<path d="M{left},{top}V{bottom}H{right}" fill="none" stroke="#777"/>']
    for j in range(selected.shape[1]):
        points=' '.join(f'{left+(right-left)*i/max(1,len(actions)-1):.2f},{bottom-(bottom-top)*(v-lo)/(hi-lo):.2f}' for i,v in enumerate(selected[:,j]))
        pieces.append(f'<polyline points="{points}" fill="none" stroke="{colors[j]}" stroke-width="2"/>')
        pieces.append(f'<text x="{60+j*140}" y="315" font-family="sans-serif" font-size="13" fill="{colors[j]}">dimension {j}</text>')
    pieces.append(f'<text x="780" y="300" font-family="sans-serif" font-size="12">last sample {(len(actions)-1)/hz:.3f}s</text></svg>')
    out.write_text('\n'.join(pieces))


def main():
    p=argparse.ArgumentParser();p.add_argument('--demo',action='store_true');p.add_argument('--actions',type=Path)
    p.add_argument('--reference',type=Path);p.add_argument('--hz',type=float,default=30);p.add_argument('--prefix',type=Path,default=Path('chunk-analysis'));a=p.parse_args()
    if a.demo:
        t=np.arange(30)/30;actions=np.stack([.1*np.sin(t+j*.2) for j in range(16)],axis=1)
        actions[15,0]+=.2;np.save('synthetic-actions.npy',actions)
    elif a.actions is not None:actions=np.load(a.actions,allow_pickle=False)
    else:p.error('Choose --demo or --actions')
    report=analyze(actions,a.hz);report['demo']=a.demo
    if a.reference is not None:
        ref=np.load(a.reference,allow_pickle=False)
        if ref.shape!=actions.shape or not np.isfinite(ref).all():raise ValueError('Reference must be finite and identically aligned/shaped')
        report['per_dimension_rmse']=np.sqrt(np.mean((actions-ref)**2,axis=0)).tolist()
        report['comparison_note']='Assumes identical units, frames and alignment; open-loop diagnostic, not task success.'
    with Path(str(a.prefix)+'.csv').open('w',newline='') as f:
        w=csv.writer(f);w.writerow(['elapsed_s']+[f'action_{i}' for i in range(actions.shape[1])])
        for i,row in enumerate(actions):w.writerow([i/a.hz,*row])
    Path(str(a.prefix)+'.json').write_text(json.dumps(report,indent=2));plot_svg(actions,a.hz,Path(str(a.prefix)+'.svg'))
    print(json.dumps(report,indent=2))
    if a.demo:
        assert report['max_adjacent_change'][0]>.19 and report['horizon_s']==1
        try:analyze(np.array([[np.nan]]),30)
        except ValueError:pass
        else:raise AssertionError('NaN accepted')
if __name__=='__main__':main()
